<section class="sec"><div class="wrap"><h2 class="sr">All initiatives</h2><div class="rows"><article class="irow rv"><span class="n">01</span><div><h3 data-bn="জলবায়ু ল্যাব"><a class="irow-a" href="{{ route('initiatives.climate-lab') }}">Delta Climate Lab</a></h3><p class="kicker">Nature & Climate</p></div>
